mapper.select:
SELECT dp.paper_id,dp.doctorName,dp.title,dp.title_hash,dp.paper_url FROM doctor_paper dp INNER JOIN doctor_basic db ON dp.rid = db.rid WHERE 1=1 and dp.title IS NOT NULL and dp.pmid IS NULL and dp.updateAt IS NULL
AND dp.data_version_id = #{version_id}
AND db.hid = #{hid}
ORDER BY dp.paper_id asc
